<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetWriteGateway;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Connector\Pdo\SnippetPdoConnector;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetSlide;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetCursor;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetFilter;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\Snippet\Domain\Snippet;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class SnippetWriteRepositoryAdapter implements SnippetWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SnippetPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(SnippetRef $ref): ?Snippet
    {
        return $this->conn->retrieveForUpdate(new SnippetFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?SnippetFilter $filter = null, ?SnippetCursor $cursor = null): SnippetSlide
    {
        $this->logDebug("List for update of Snippet on adapter ");
        $span = $this->startSpan("List for update of Snippet on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new SnippetSlide(function (SnippetSlide $slide, ?SnippetCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new SnippetCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(SnippetFilter $filter): ?Snippet
    {
        $this->logDebug("Retrieve for update of Snippet on adapter ");
        $span = $this->startSpan("Retrieve for update of Snippet on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(SnippetFilter $filter): bool
    {
        $this->logDebug("Exists for update of Snippet on adapter ");
        $span = $this->startSpan("Exists for update of Snippet on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?SnippetFilter $filter = null): int
    {
        $this->logDebug("Count for update of Snippet on adapter ");
        $span = $this->startSpan("Count for update of Snippet on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(Snippet $entity, ?Closure $verify = null): Snippet
    {
        $this->logDebug("Count for Snippet on adapter ");
        $span = $this->startSpan("Count for Snippet on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('snippet', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(SnippetRef $ref, Snippet $entity): Snippet
    {
        $this->logDebug("Count for Snippet on adapter ");
        $span = $this->startSpan("Count for Snippet on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('snippet', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(Snippet $entity): bool
    {
        $this->logDebug("Count for Snippet on adapter ");
        $span = $this->startSpan("Count for Snippet on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('snippet', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByCodeAndTenant(string $code, ?TenantRef $tenant): ?Snippet
    {
        $this->logDebug("Find on by code tenant for Snippet on adapter");
        $span = $this->startSpan("Find on by code tenant for Snippet on adapter");
        try {
            return $this->conn->retrieveForUpdate(new SnippetFilter(codeAndTenant: SnippetFilter::codeAndTenantFilter(code: $code, tenant: $tenant)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(Snippet $entity): void
    {
        $this->logDebug("Count for Snippet on adapter ");
        $span = $this->startSpan("Count for Snippet on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
